insert into public.flags (id, app, target_type, target_id, reporter_id, kind, message, contact_email, created_at, resolved_at) values ('a49cf0d8-0583-4e48-addf-c3cf0520192d', 'restroom-map', 'bathroom', 'd0157c26-f4da-42de-bb7c-10de603b057f', NULL, 'user', 'hidden by operator: testing the kill switch', NULL, '2026-09-12 01:27:42.548402+00', '2026-09-12 01:27:42.548402+00') on conflict (id) do nothing;
insert into public.flags (id, app, target_type, target_id, reporter_id, kind, message, contact_email, created_at, resolved_at) values ('71f8a95d-433a-40ed-aaa6-897a47f6aa1e', 'restroom-map', 'bathroom', 'd0157c26-f4da-42de-bb7c-10de603b057f', NULL, 'user', 'hidden by operator: test data from development, not a real place', NULL, '2026-09-15 00:20:11.069137+00', '2026-09-15 00:20:11.069137+00') on conflict (id) do nothing;
insert into public.feedback (id, app, kind, message, contact_email, user_id, build, created_at, resolved_at) values ('e157a622-8441-4d0a-8d64-9ecd48ca5aaa', 'restroom-map', 'bug', '[ui-audit finding, not a user report] "Address optional" and "How to find it optional" read as single phrases in the add-a-place form. The "optional" is an <em> that used to be faded; the fade was removed because it failed colour contrast, and the 0.94em size left in its place is not enough to read as secondary. Needs a different treatment - parentheses, or a separate line.', NULL, NULL, 'v99', '2026-09-16 13:00:58.059696+00', '2026-09-16 16:07:27.34476+00') on conflict (id) do nothing;
insert into public.feedback (id, app, kind, message, contact_email, user_id, build, created_at, resolved_at) values ('c0f2aab7-9ae1-4e7d-9fa3-6b916a105de2', 'restroom-map', 'bug', '[ui-audit finding, not a user report] In the nearby prompt, "Not now" is 36px tall while "Worked" and "Wasn''t there" beside it are 44px. Measured at 375x812 with a fix at 40.705277,-74.005516. It is the dismiss action, so it is the one somebody in a hurry reaches for.', NULL, NULL, 'v99', '2026-09-16 13:00:58.025169+00', '2026-09-16 16:07:27.635694+00') on conflict (id) do nothing;
insert into public.feedback (id, app, kind, message, contact_email, user_id, build, created_at, resolved_at) values ('fdc6b32f-02fe-49a2-bc3c-585306aa0e63', 'restroom-map', 'bug', '[ui-audit finding, not a user report] Every control in the add-a-place sheet is under the 44px touch target: Cancel and "Add it" are 38px, the "move" link is 21px, and the name/address/hint inputs and both selects are 38-39px. Measured at 375x812. The detail sheet was raised to 44px but the add flow was missed, which is the contribution path.', NULL, NULL, 'v99', '2026-09-16 13:00:57.876674+00', '2026-09-16 16:07:27.917237+00') on conflict (id) do nothing;
